use indicators::{Percentage, ProgressBar};

fn main() {
    let _args: Vec<String> = std::env::args().collect();

    let mut bar = ProgressBar::new();
    bar.set_progress(75);
    bar.set_total(100);
    bar.set_width(30);
    println!("{}", bar.str());

    let pct = Percentage::new(0.75_f32);
    println!("{}", pct.str());
}

#[derive(Debug, Clone, PartialEq)]
pub struct ProgressBar {
    progress: usize,
    total: usize,
    width: usize,
}

impl Default for ProgressBar {
    fn default() -> Self {
        Self {
            progress: 0,
            total: 100,
            width: 50,
        }
    }
}

impl ProgressBar {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: usize) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: usize) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: usize) {
        self.width = width;
    }

    pub fn str(&self) -> String {
        let ratio = if self.total == 0 {
            0.0_f32
        } else {
            self.progress as f32 / self.total as f32
        };

        let filled = ((ratio * self.width as f32).floor() as isize).clamp(0, self.width as isize) as usize;
        let bar = if self.width == 0 {
            String::new()
        } else if filled >= self.width {
            "=".repeat(self.width)
        } else {
            let mut bar = String::with_capacity(self.width);
            bar.push_str(&"=".repeat(filled));
            bar.push('>');
            bar.push_str(&" ".repeat(self.width.saturating_sub(filled + 1)));
            bar
        };

        format!("[{}] {:.1}%", bar, ratio * 100.0)
    }
}

